20	      const payload = flow(omit("type"), omit("entity"))(event);
21	      const resp = await httpClient.post(
22	        `http://localhost:${backendPort}/${route}/${payload.transactionId}`,
23	        payload
24	      );
25	      return resp.data;
26	    },
27	    updateData: async (ctx, event: any) => {
28	      const payload = omit("type", event);
29	      const contextTransactionId = !isEmpty(ctx.results) && first(ctx.results)["id"];
30	      const transactionId = contextTransactionId || payload.id;
31	      const resp = await httpClient.patch(
32	        `http://localhost:${backendPort}/transactions/${transactionId}`,
33	        payload
34	      );
