8	export interface AuthMachineSchema {
9	  states: {
10	    unauthorized: {};
11	    signup: {};
12	    loading: {};
13	    updating: {};
14	    logout: {};
15	    refreshing: {};
16	    google: {};
17	    authorized: {};
18	    auth0: {};
19	    cognito: {};
20	    okta: {};
21	  };
22	}
23	
24	export type AuthMachineEvents =
25	  | { type: "LOGIN" }
26	  | { type: "LOGOUT" }
27	  | { type: "UPDATE" }
28	  | { type: "REFRESH" }
29	  | { type: "AUTH0" }
30	  | { type: "COGNITO" }
31	  | { type: "OKTA" }
32	  | { type: "GOOGLE" }
33	  | { type: "SIGNUP" };
34	
35	export interface AuthMachineContext {
36	  user?: User;
37	  message?: string;
38	}
39	
40	export const authMachine = Machine<AuthMachineContext, AuthMachineSchema, AuthMachineEvents>(
41	  {
42	    id: "authentication",
43	    initial: "unauthorized",
44	    context: {
45	      user: undefined,
46	      message: undefined,
47	    },
48	    states: {
49	      unauthorized: {
50	        entry: "resetUser",
51	        on: {
52	          LOGIN: "loading",
53	          SIGNUP: "signup",
54	          GOOGLE: "google",
55	          AUTH0: "auth0",
56	          OKTA: "okta",
57	          COGNITO: "cognito",
58	        },
59	      },
60	      signup: {
61	        invoke: {
62	          src: "performSignup",
63	          onDone: { target: "unauthorized", actions: "onSuccess" },
64	          onError: { target: "unauthorized", actions: "onError" },
65	        },
66	      },
67	      loading: {
68	        invoke: {
69	          src: "performLogin",
70	          onDone: { target: "authorized", actions: "onSuccess" },
71	          onError: { target: "unauthorized", actions: "onError" },
72	        },
73	      },
74	      updating: {
75	        invoke: {
76	          src: "updateProfile",
77	          onDone: { target: "refreshing" },
78	          onError: { target: "unauthorized", actions: "onError" },
79	        },
80	      },
81	      refreshing: {
82	        invoke: {
83	          src: "getUserProfile",
84	          onDone: { target: "authorized", actions: "setUserProfile" },
85	          onError: { target: "unauthorized", actions: "onError" },
86	        },
87	        on: {
88	          LOGOUT: "logout",
89	        },
90	      },
91	      google: {
92	        invoke: {
93	          src: "getGoogleUserProfile",
94	          onDone: { target: "authorized", actions: "setUserProfile" },
95	          onError: { target: "unauthorized", actions: "onError" },
96	        },
97	        on: {
98	          LOGOUT: "logout",
99	        },
100	      },
101	      logout: {
102	        invoke: {
103	          src: "performLogout",
104	          onDone: { target: "unauthorized" },
105	          onError: { target: "unauthorized", actions: "onError" },
106	        },
107	      },
108	      authorized: {
109	        entry: "redirectHomeAfterLogin",
110	        on: {
111	          UPDATE: "updating",
112	          REFRESH: "refreshing",
113	          LOGOUT: "logout",
114	        },
115	      },
116	      auth0: {
117	        invoke: {
118	          src: "getAuth0UserProfile",
119	          onDone: { target: "authorized", actions: "setUserProfile" },
120	          onError: { target: "unauthorized", actions: "onError" },
121	        },
122	        on: {
123	          LOGOUT: "logout",
124	        },
125	      },
126	      okta: {
127	        invoke: {
128	          src: "getOktaUserProfile",
129	          onDone: { target: "authorized", actions: "setUserProfile" },
130	          onError: { target: "unauthorized", actions: "onError" },
131	        },
132	        on: {
133	          LOGOUT: "logout",
134	        },
135	      },
136	      cognito: {
137	        invoke: {
138	          src: "getCognitoUserProfile",
139	          onDone: { target: "authorized", actions: "setUserProfile" },
140	          onError: { target: "unauthorized", actions: "onError" },
141	        },
142	        on: {
143	          LOGOUT: "logout",
144	        },
145	      },
146	    },
147	  },
148	  {
149	    services: {
150	      performSignup: async (ctx, event) => {
151	        const payload = omit("type", event);
152	        const resp = await httpClient.post(`http://localhost:${backendPort}/users`, payload);
153	        history.push("/signin");
154	        return resp.data;
155	      },
156	      performLogin: async (ctx, event) => {
157	        return await httpClient
158	          .post(`http://localhost:${backendPort}/login`, event)
159	          .then(({ data }) => {
160	            history.push("/");
161	            return data;
162	          })
163	          .catch((error) => {
164	            throw new Error("Username or password is invalid");
165	          });
166	      },
167	      getOktaUserProfile: /* istanbul ignore next */ (ctx, event: any) => {
168	        // Map Okta User fields to our User Model
169	        const user = {
170	          id: event.user.sub,
171	          email: event.user.email,
172	          firstName: event.user.given_name,
173	          lastName: event.user.family_name,
174	          username: event.user.preferred_username,
175	        };
176	
177	        // Set Access Token in Local Storage for API calls
178	        localStorage.setItem(process.env.VITE_AUTH_TOKEN_NAME!, event.token);
179	
180	        return Promise.resolve({ user });
181	      },
182	      getUserProfile: async (ctx, event) => {
183	        const resp = await httpClient.get(`http://localhost:${backendPort}/checkAuth`);
184	        return resp.data;
185	      },
186	      getGoogleUserProfile: /* istanbul ignore next */ (ctx, event: any) => {
187	        // Map Google User fields to our User Model
188	        const user = {
189	          id: event.user.googleId,
190	          email: event.user.email,
191	          firstName: event.user.givenName,
192	          lastName: event.user.familyName,
193	          avatar: event.user.imageUrl,
194	        };
195	
196	        // Set Google Access Token in Local Storage for API calls
197	        localStorage.setItem(process.env.VITE_AUTH_TOKEN_NAME!, event.token);
198	
199	        return Promise.resolve({ user });
200	      },
201	      getAuth0UserProfile: /* istanbul ignore next */ (ctx, event: any) => {
202	        // Map Auth0 User fields to our User Model
203	        const user = {
204	          id: event.user.sub,
205	          email: event.user.email,
206	          firstName: event.user.nickname,
207	          avatar: event.user.picture,
208	        };
209	
210	        // Set Auth0 Access Token in Local Storage for API calls
211	        localStorage.setItem(process.env.VITE_AUTH_TOKEN_NAME!, event.token);
212	
213	        return Promise.resolve({ user });
214	      },
215	      updateProfile: async (ctx, event: any) => {
216	        const payload = omit("type", event);
217	        const resp = await httpClient.patch(
218	          `http://localhost:${backendPort}/users/${payload.id}`,
219	          payload
220	        );
221	        return resp.data;
222	      },
223	      performLogout: async (ctx, event) => {
224	        localStorage.removeItem("authState");
225	        return await httpClient.post(`http://localhost:${backendPort}/logout`);
226	      },
227	      getCognitoUserProfile: /* istanbul ignore next */ (ctx, event: any) => {
228	        // Map Cognito User fields to our User Model
229	        const ourUser = {
230	          id: event.userSub,
231	          email: event.email,
232	        };
233	
234	        // Set Access Token in Local Storage for API calls
235	        localStorage.setItem(process.env.VITE_AUTH_TOKEN_NAME!, event.accessTokenJwtString);
236	
237	        return Promise.resolve(ourUser);
238	      },
