import { createRequire } from 'module';
const require = createRequire(import.meta.url);
const { chromium } = require('/Users/stephenhe/Projects/capybara-benchmark/projects/cypress-realworld-app/node_modules/playwright');

const BASE_URL = 'http://localhost:3013';
const CREDS = { username: 'Heath93', password: 's3cret' };

async function loginAndGoTo(page, path) {
  await page.goto(`${BASE_URL}/signin`);
  await page.waitForLoadState('networkidle');
  await page.locator('[data-test=signin-username] input').fill(CREDS.username);
  await page.locator('[data-test=signin-password] input').fill(CREDS.password);
  await page.locator('[data-test=signin-submit]').click();
  await page.waitForTimeout(3000);
  await page.waitForLoadState('networkidle');
  if (path !== '/') {
    await page.goto(`${BASE_URL}${path}`);
    await page.waitForLoadState('networkidle');
    await page.waitForTimeout(1000);
  }
}

async function main() {
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext();
  const page = await context.newPage();

  const results = [];

  await loginAndGoTo(page, '/');

  // Test filter overlays
  await page.locator('[data-test=transaction-list-filter-date-range-button]').click();
  await page.waitForTimeout(500);
  const dateFilterOpen = await page.locator('[data-test=transaction-list-filter-date-range]').count();
  const dateFilterClearBtn = await page.locator('[data-test=transaction-list-filter-date-clear-button]').count();
  results.push({
    page: '/#date-filter',
    hasDateFilter: dateFilterOpen > 0,
    hasClearBtn: dateFilterClearBtn > 0
  });

  // Close date filter (click escape or outside)
  await page.keyboard.press('Escape');
  await page.waitForTimeout(300);

  // Open amount filter  
  await page.locator('[data-test=transaction-list-filter-amount-range-button]').click();
  await page.waitForTimeout(500);
  const amountFilterOpen = await page.locator('[data-test=transaction-list-filter-amount-range-slider]').count();
  results.push({
    page: '/#amount-filter',
    hasAmountSlider: amountFilterOpen > 0
  });
  await page.keyboard.press('Escape');
  await page.waitForTimeout(300);

  // Test transaction detail
  const firstTransaction = page.locator('[data-test^=transaction-item-]').first();
  if (await firstTransaction.count() > 0) {
    await firstTransaction.click();
    await page.waitForLoadState('networkidle');
    await page.waitForTimeout(1000);
    const txUrl = page.url();
    const likeBtn = await page.locator('[data-test^=transaction-like-button-]').count();
    const commentInput = await page.locator('[data-test^=transaction-comment-input-]').count();
    const acceptBtn = await page.locator('[data-test^=transaction-accept-request-]').count();
    const rejectBtn = await page.locator('[data-test^=transaction-reject-request-]').count();
    results.push({
      page: '/transaction/:id',
      url: txUrl,
      hasLikeButton: likeBtn > 0,
      hasCommentInput: commentInput > 0,
      hasAcceptBtn: acceptBtn > 0,
      hasRejectBtn: rejectBtn > 0
    });
  }

  // Test transaction/new step navigation
  await page.goto(`${BASE_URL}/transaction/new`);
  await page.waitForLoadState('networkidle');
  await page.waitForTimeout(1000);

  // Step 1 - search and pick user
  const userItems = await page.locator('[data-test^=user-list-item-]').count();
  results.push({
    page: '/transaction/new#step-1',
    userListCount: userItems,
    hasSearchInput: await page.locator('[data-test=user-list-search-input]').count() > 0
  });

  if (userItems > 0) {
    await page.locator('[data-test^=user-list-item-]').first().click();
    await page.waitForTimeout(500);

    // Step 2
    const amountInput = await page.locator('[data-test=transaction-create-amount-input]').count();
    const descInput = await page.locator('[data-test=transaction-create-description-input]').count();
    const payBtn = await page.locator('[data-test=transaction-create-submit-payment]').count();
    const requestBtn = await page.locator('[data-test=transaction-create-submit-request]').count();
    results.push({
      page: '/transaction/new#step-2',
      hasAmountInput: amountInput > 0,
      hasDescriptionInput: descInput > 0,
      hasPayButton: payBtn > 0,
      hasRequestButton: requestBtn > 0
    });

    // Fill and pay
    await page.locator('[data-test=transaction-create-amount-input] input').fill('50');
    await page.locator('[data-test=transaction-create-description-input] input').fill('Test payment');
    await page.locator('[data-test=transaction-create-submit-payment]').click();
    await page.waitForTimeout(1000);

    // Step 3
    const returnBtn = await page.locator('[data-test=new-transaction-return-to-transactions]').count();
    const createAnotherBtn = await page.locator('[data-test=new-transaction-create-another-transaction]').count();
    results.push({
      page: '/transaction/new#step-3',
      hasReturnButton: returnBtn > 0,
      hasCreateAnotherButton: createAnotherBtn > 0
    });
  }

  // Test bankaccounts/new
  await page.goto(`${BASE_URL}/bankaccounts/new`);
  await page.waitForLoadState('networkidle');
  await page.waitForTimeout(500);
  results.push({
    page: '/bankaccounts/new',
    url: page.url(),
    hasBankNameInput: await page.locator('[data-test=bankaccount-bankName-input]').count() > 0,
    hasRoutingInput: await page.locator('[data-test=bankaccount-routingNumber-input]').count() > 0,
    hasAccountInput: await page.locator('[data-test=bankaccount-accountNumber-input]').count() > 0,
    hasSaveButton: await page.locator('[data-test=bankaccount-submit]').count() > 0
  });

  await browser.close();
  console.log(JSON.stringify(results, null, 2));
}

main().catch(err => { console.error('ERROR:', err.message, err.stack); process.exit(1); });
